import java.util.*;
import java.io.*;

public class Main {
    // Return {start, last, v0, v1, ...}: the loop start label and last node label
    // (both -1 if there is no loop), followed by the values from the head after removal.
    static long[] removeLoop(long[] val, int[] nxt) {
        // Write your solution here
        return new long[]{-1, -1};
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        long[] val = new long[n];
        int[] nxt = new int[n];
        for (int i = 0; i < n; i++) {
            in.nextToken(); val[i] = (long) in.nval;
            in.nextToken(); nxt[i] = (int) in.nval;
        }
        long[] res = removeLoop(val, nxt);
        StringBuilder sb = new StringBuilder();
        sb.append(res[0]).append(" ").append(res[1]).append("\n");
        for (int i = 2; i < res.length; i++) sb.append(res[i]).append(i + 1 < res.length ? " " : "");
        sb.append("\n");
        System.out.print(sb);
    }
}
